escenas.drawCode:
drawBackgroundGrid(F, 0.2);
const A = F.area, cx = A.cx, cy = A.cy;
const kCard = pop(t, 0.1, 0.5);

const cw = A.w * 0.88, ch = A.h * 0.72;
ctx.save();
ctx.globalAlpha = kCard;
ctx.translate(cx, cy);
ctx.scale(kCard, kCard);

ctx.fillStyle = 'rgba(0,0,0,0.45)';
rrect(-cw / 2, -ch / 2 + 2, cw, ch, 14); ctx.fill();

ctx.fillStyle = C.panel;
ctx.strokeStyle = C.line;
ctx.lineWidth = 0.8;
rrect(-cw / 2, -ch / 2, cw, ch, 14); ctx.fill(); ctx.stroke();

ctx.fillStyle = C.panel2;
rrect(-cw / 2, -ch / 2, cw, ch * 0.24, [14, 14, 0, 0]); ctx.fill();

medicalBadge(-cw * 0.32, -ch * 0.38, 7, 1);
txt('CAMPUS ESALUD', -cw * 0.05, -ch * 0.38, { size: 4.2, color: C.ink, align: 'left', w: 800 });

const pSize = 14;
ctx.fillStyle = C.panel2;
ctx.strokeStyle = C.accent;
ctx.lineWidth = 0.8;
ctx.beginPath(); ctx.arc(0, -ch * 0.04, pSize, 0, TAU); ctx.fill(); ctx.stroke();
medicalBadge(0, -ch * 0.04, 9, 0.85);

txt('PROGRAMA RESIDENCIAS', 0, ch * 0.18, { size: 3.6, color: C.accent, w: 700 });
txt('COHORTE 2026 / 2027', 0, ch * 0.27, { size: 4.8, color: C.ink, w: 900 });

const bw = cw * 0.65, bh = ch * 0.11;
ctx.fillStyle = rgba(C.ok, 0.16);
ctx.strokeStyle = C.ok;
ctx.lineWidth = 0.6;
rrect(-bw / 2, ch * 0.35, bw, bh, 6); ctx.fill(); ctx.stroke();
checkBadge(-bw * 0.36, ch * 0.405, 2.4, 1);
txt('AUTOMATRICULACIÓN ACTIVA', bw * 0.04, ch * 0.405, { size: 2.7, color: C.ok, w: 800 });

ctx.restore();

drawBackgroundGrid(F, 0.2);
const A = F.area, cx = A.cx, cy = A.cy;
const kBox = pop(t, 0.1, 0.4);

const bw = A.w * 0.9, bh = A.h * 0.74;
ctx.save();
ctx.globalAlpha = kBox;
ctx.translate(cx, cy);

ctx.fillStyle = C.panel;
ctx.strokeStyle = C.line;
ctx.lineWidth = 0.8;
rrect(-bw / 2, -bh / 2, bw, bh, 12); ctx.fill(); ctx.stroke();

txt('INICIAR SESIÓN', 0, -bh * 0.36, { size: 4.4, color: C.accent, w: 800 });
txt('Campus Virtual de Salud', 0, -bh * 0.28, { size: 3.2, color: C.muted, w: 500 });

const fldW = bw * 0.82, fldH = 8.5;
ctx.fillStyle = C.panel2;
ctx.strokeStyle = C.line;
ctx.lineWidth = 0.6;
rrect(-fldW / 2, -bh * 0.14, fldW, fldH, 6); ctx.fill(); ctx.stroke();
txt('Usuario / DNI de residente', -fldW * 0.42, -bh * 0.14 + fldH * 0.5, { size: 2.8, color: C.ink, align: 'left', w: 500 });

rrect(-fldW / 2, bh * 0.04, fldW, fldH, 6); ctx.fill(); ctx.stroke();
txt('● ● ● ● ● ● ● ● ● ●', -fldW * 0.42, bh * 0.04 + fldH * 0.5, { size: 3.2, color: C.accent, align: 'left', w: 600 });

const kPulse = 1 + 0.04 * Math.sin(t * 5);
ctx.save();
ctx.translate(0, bh * 0.21);
ctx.scale(kPulse, kPulse);
ctx.fillStyle = C.accent;
rrect(-fldW / 2, -fldH / 2, fldW, fldH, 6); ctx.fill();
txt('INGRESAR AL CAMPUS', 0, 0, { size: 3.2, color: '#041B22', w: 800 });
ctx.restore();

const kRecup = ease(seg(t, 2.5, 3.2));
if (kRecup > 0) {
  ctx.save();
  ctx.globalAlpha = kRecup;
  ctx.fillStyle = rgba(C.accent2, 0.12);
  ctx.strokeStyle = C.accent2;
  ctx.lineWidth = 0.5;
  rrect(-fldW / 2, bh * 0.32, fldW, 8.5, 6); ctx.fill(); ctx.stroke();
  padlock(-fldW * 0.38, bh * 0.32 + 3.8, 2.6, 0.2);
  txt('¿Olvidaste tu contraseña?', -fldW * 0.24, bh * 0.32 + 4.25, { size: 2.6, color: C.ink, align: 'left', w: 700 });
  txt('Usá la opción de recupero antes de pedir nuevo usuario', 0, bh * 0.44, { size: 2.4, color: C.muted, w: 500 });
  ctx.restore();
}

ctx.restore();

drawBackgroundGrid(F, 0.2);
const A = F.area, cx = A.cx, cy = A.cy;

const sw = A.w * 0.9, sh = 9.5;
const kSearch = pop(t, 0.1, 0.4);
ctx.save();
ctx.globalAlpha = kSearch;
ctx.fillStyle = C.panel;
ctx.strokeStyle = C.accent;
ctx.lineWidth = 0.8;
rrect(cx - sw / 2, cy - A.h * 0.36, sw, sh, 8); ctx.fill(); ctx.stroke();

const lx = cx - sw * 0.42, ly = cy - A.h * 0.36 + sh * 0.5;
ctx.strokeStyle = C.accent; ctx.lineWidth = 0.8;
ctx.beginPath(); ctx.arc(lx, ly, 2.2, 0, TAU); ctx.stroke();
line(lx + 1.6, ly + 1.6, lx + 3.2, ly + 3.2);

const typed = 'Competencias Residentes...'.slice(0, Math.floor(seg(t, 0.4, 2.2) * 26));
txt(typed, lx + 5.5, ly, { size: 3.2, color: C.ink, align: 'left', family: FONT.mono, w: 600 });
ctx.restore();

const cardW = sw, cardH = 15;
const kCard1 = pop(t, 1.2, 0.4);
const kCard2 = pop(t, 2.0, 0.4);

if (kCard1 > 0) {
  ctx.save();
  ctx.globalAlpha = kCard1;
  const y1 = cy - A.h * 0.15;
  ctx.fillStyle = C.panel;
  ctx.strokeStyle = C.line;
  ctx.lineWidth = 0.7;
  rrect(cx - cardW / 2, y1, cardW, cardH, 10); ctx.fill(); ctx.stroke();

  ctx.fillStyle = rgba(C.accent, 0.18);
  rrect(cx - cardW * 0.44, y1 + 2.5, 10, 10, 4); ctx.fill();
  medicalBadge(cx - cardW * 0.44 + 5, y1 + 7.5, 4.5, 1);

  txt('CURSO 1: HERRAMIENTAS DE GESTIÓN', cx - cardW * 0.26, y1 + 5.2, { size: 3.0, color: C.accent, align: 'left', w: 800 });
  txt('Programa Competencias Residentes', cx - cardW * 0.26, y1 + 10.2, { size: 2.5, color: C.muted, align: 'left', w: 500 });
  checkBadge(cx + cardW * 0.42, y1 + 7.5, 2.4, 1);
  ctx.restore();
}

if (kCard2 > 0) {
  ctx.save();
  ctx.globalAlpha = kCard2;
  const y2 = cy + A.h * 0.05;
  ctx.fillStyle = C.panel;
  ctx.strokeStyle = C.line;
  ctx.lineWidth = 0.7;
  rrect(cx - cardW / 2, y2, cardW, cardH, 10); ctx.fill(); ctx.stroke();

  ctx.fillStyle = rgba(C.accent2, 0.18);
  rrect(cx - cardW * 0.44, y2 + 2.5, 10, 10, 4); ctx.fill();
  ctx.strokeStyle = C.accent2; ctx.lineWidth = 0.8;
  line(cx - cardW * 0.44 + 2, y2 + 10, cx - cardW * 0.44 + 5, y2 + 6);
  line(cx - cardW * 0.44 + 5, y2 + 6, cx - cardW * 0.44 + 8, y2 + 4);

  txt('CURSO 2: ECONOMÍA DE LA SALUD', cx - cardW * 0.26, y2 + 5.2, { size: 3.0, color: C.accent2, align: 'left', w: 800 });
  txt('Para Residentes · Autogestionado', cx - cardW * 0.26, y2 + 10.2, { size: 2.5, color: C.muted, align: 'left', w: 500 });
  checkBadge(cx + cardW * 0.42, y2 + 7.5, 2.4, 1);
  ctx.restore();
}

if (t > 3.0) {
  const kArrow = pop(t, 3.0, 0.3);
  ctx.save();
  ctx.globalAlpha = kArrow;
  txt('Seleccioná el curso para matricularte ➔', cx, cy + A.h * 0.28, { size: 3.2, color: C.ink, w: 700 });
  ctx.restore();
}

drawBackgroundGrid(F, 0.2);
const A = F.area, cx = A.cx, cy = A.cy;

txt('CLAVES DE AUTOMATRICULACIÓN', cx, cy - A.h * 0.34, { size: 4.2, color: C.ink, w: 900 });
txt('Ingresá la clave institucional que corresponda:', cx, cy - A.h * 0.27, { size: 2.9, color: C.muted, w: 500 });

const boxW = A.w * 0.92, boxH = 18;

const k1 = pop(t, 0.3, 0.4);
if (k1 > 0) {
  ctx.save();
  ctx.globalAlpha = k1;
  const y1 = cy - A.h * 0.12;
  ctx.fillStyle = C.panel;
  ctx.strokeStyle = C.accent;
  ctx.lineWidth = 1;
  rrect(cx - boxW / 2, y1, boxW, boxH, 10); ctx.fill(); ctx.stroke();

  txt('CURSO DE GESTIÓN EN SALUD', cx - boxW * 0.42, y1 + 4.5, { size: 2.8, color: C.muted, align: 'left', w: 700 });

  ctx.fillStyle = C.panel2;
  rrect(cx - boxW * 0.44, y1 + 7.5, boxW * 0.88, 8, 6); ctx.fill();
  padlock(cx - boxW * 0.36, y1 + 10.5, 2.2, 1);
  txt('Ges.residentes2026*', cx - boxW * 0.26, y1 + 11.5, { size: 3.6, color: C.accent, family: FONT.mono, align: 'left', w: 800 });
  ctx.restore();
}

const k2 = pop(t, 1.8, 0.4);
if (k2 > 0) {
  ctx.save();
  ctx.globalAlpha = k2;
  const y2 = cy + A.h * 0.10;
  ctx.fillStyle = C.panel;
  ctx.strokeStyle = C.accent2;
  ctx.lineWidth = 1;
  rrect(cx - boxW / 2, y2, boxW, boxH, 10); ctx.fill(); ctx.stroke();

  txt('CURSO DE ECONOMÍA DE LA SALUD', cx - boxW * 0.42, y2 + 4.5, { size: 2.8, color: C.muted, align: 'left', w: 700 });

  ctx.fillStyle = C.panel2;
  rrect(cx - boxW * 0.44, y2 + 7.5, boxW * 0.88, 8, 6); ctx.fill();
  padlock(cx - boxW * 0.36, y2 + 10.5, 2.2, 1);
  txt('Eco.residentes206*', cx - boxW * 0.26, y2 + 11.5, { size: 3.6, color: C.accent2, family: FONT.mono, align: 'left', w: 800 });
  ctx.restore();
}

if (t > 3.0) {
  const kInfo = pop(t, 3.0, 0.3);
  ctx.save();
  ctx.globalAlpha = kInfo;
  txt('¡Respetá mayúsculas, puntos y asteriscos!', cx, cy + A.h * 0.32, { size: 3.0, color: C.ok, w: 700 });
  ctx.restore();
}

drawBackgroundGrid(F, 0.2);
const A = F.area, cx = A.cx, cy = A.cy;
const kAll = pop(t, 0.2, 0.5);

ctx.save();
ctx.globalAlpha = kAll;

const kPadlock = pop(t, 0.6, 0.5);
padlock(cx, cy - A.h * 0.16, 12 * kPadlock, 0, 1);

checkBadge(cx + 12, cy - A.h * 0.22, 5, pop(t, 1.2, 0.3));

txt('AULA HABILITADA', cx, cy + A.h * 0.04, { size: 5.2, color: C.ok, w: 900 });
txt('Acceso Permanente Garantizado', cx, cy + A.h * 0.12, { size: 3.4, color: C.ink, w: 700 });

const cw = A.w * 0.88, ch = 9;
ctx.fillStyle = C.panel;
ctx.strokeStyle = C.line;
ctx.lineWidth = 0.6;
rrect(cx - cw / 2, cy + A.h * 0.20, cw, ch, 6); ctx.fill(); ctx.stroke();
txt('⏱ Cursado 100% autoadministrado a tu ritmo', cx, cy + A.h * 0.20 + ch * 0.5, { size: 2.8, color: C.muted, w: 600 });

rrect(cx - cw / 2, cy + A.h * 0.28, cw, ch, 6); ctx.fill(); ctx.stroke();
txt('📂 Materiales, evaluaciones y certificados activos', cx, cy + A.h * 0.28 + ch * 0.5, { size: 2.8, color: C.muted, w: 600 });

ctx.restore();

drawBackgroundGrid(F, 0.2);
const A = F.area, cx = A.cx, cy = A.cy;

txt('¿NO TENÉS USUARIO?', cx, cy - A.h * 0.34, { size: 4.4, color: C.warn, w: 900 });
txt('Procedimiento para nuevas altas:', cx, cy - A.h * 0.27, { size: 3.0, color: C.muted, w: 500 });

const fw = A.w * 0.9, fh = 16;
const kForm = pop(t, 0.3, 0.4);

if (kForm > 0) {
  ctx.save();
  ctx.globalAlpha = kForm;
  const y1 = cy - A.h * 0.12;
  ctx.fillStyle = C.panel;
  ctx.strokeStyle = C.line;
  ctx.lineWidth = 0.7;
  rrect(cx - fw / 2, y1, fw, fh, 10); ctx.fill(); ctx.stroke();

  ctx.fillStyle = rgba(C.accent, 0.2);
  rrect(cx - fw * 0.43, y1 + 3, 10, 10, 4); ctx.fill();
  txt('📝', cx - fw * 0.43 + 5, y1 + 8, { size: 4.5 });

  txt('1. Contactá a Residencias', cx - fw * 0.24, y1 + 5.5, { size: 3.2, color: C.ink, align: 'left', w: 800 });
  txt('Completá el formulario online de alta', cx - fw * 0.24, y1 + 10.5, { size: 2.6, color: C.muted, align: 'left', w: 500 });
  ctx.restore();
}

const kClock = pop(t, 1.8, 0.4);
if (kClock > 0) {
  ctx.save();
  ctx.globalAlpha = kClock;
  const y2 = cy + A.h * 0.08;
  ctx.fillStyle = C.panel;
  ctx.strokeStyle = C.accent;
  ctx.lineWidth = 1;
  rrect(cx - fw / 2, y2, fw, fh + 4, 10); ctx.fill(); ctx.stroke();

  ctx.fillStyle = rgba(C.accent, 0.2);
  rrect(cx - fw * 0.43, y2 + 3.5, 12, 12, 4); ctx.fill();
  txt('📅', cx - fw * 0.43 + 6, y2 + 9.5, { size: 5.0 });

  txt('2. Cronograma de Procesamiento', cx - fw * 0.22, y2 + 5.5, { size: 3.1, color: C.accent, align: 'left', w: 800 });
  txt('Cargas semanales: hasta VIERNES 12:00 hs', cx - fw * 0.22, y2 + 10.5, { size: 2.6, color: C.ink, align: 'left', w: 700 });
  txt('Capacitación procesa los pedidos masivamente', cx - fw * 0.22, y2 + 14.5, { size: 2.4, color: C.muted, align: 'left', w: 500 });
  ctx.restore();
}

drawBackgroundGrid(F, 0.2);
const A = F.area, cx = A.cx, cy = A.cy;
const kEnd = pop(t, 0.2, 0.5);

ctx.save();
ctx.globalAlpha = kEnd;

const cw = A.w * 0.92, ch = A.h * 0.7;
ctx.fillStyle = C.panel;
ctx.strokeStyle = C.line;
ctx.lineWidth = 0.8;
rrect(cx - cw / 2, cy - ch / 2, cw, ch, 14); ctx.fill(); ctx.stroke();

const kMail = pop(t, 0.6, 0.4);
ctx.save();
ctx.translate(cx, cy - ch * 0.24);
ctx.scale(kMail, kMail);
ctx.fillStyle = rgba(C.accent, 0.16);
ctx.strokeStyle = C.accent;
ctx.lineWidth = 0.8;
rrect(-14, -10, 28, 20, 6); ctx.fill(); ctx.stroke();
ctx.beginPath(); ctx.moveTo(-14, -10); ctx.lineTo(0, 2); ctx.lineTo(14, -10); ctx.stroke();
ctx.restore();

txt('SOPORTE Y MESA DE AYUDA', cx, cy - ch * 0.04, { size: 4.2, color: C.ink, w: 900 });
txt('Departamento de Capacitación (MinSalud)', cx, cy + ch * 0.04, { size: 2.9, color: C.muted, w: 600 });

const mw = cw * 0.9, mh = 10;
ctx.fillStyle = C.panel2;
ctx.strokeStyle = C.accent;
ctx.lineWidth = 0.7;
rrect(cx - mw / 2, cy + ch * 0.12, mw, mh, 6); ctx.fill(); ctx.stroke();
txt('deptocapacitacionminsalud@mendoza.gov.ar', cx, cy + ch * 0.12 + mh * 0.5, { size: 2.5, color: C.accent, family: FONT.mono, w: 700 });

txt('¡Éxitos en tu formación profesional!', cx, cy + ch * 0.32, { size: 3.4, color: C.ok, w: 800 });

ctx.restore();
